SELECT YEAR(HolidayDate) AS Yr, COUNT(*) AS N, SUM(CASE WHEN ActiveFlag = 1 THEN 1 ELSE 0 END) AS Active
FROM   dbo.SYS_PublicHoliday WHERE CountryCode = 'US' GROUP BY YEAR(HolidayDate) ORDER BY Yr;
